class Bank(private val balance:LongArray){private fun valid(account:Int)=account in 1..balance.size;fun transfer(account1:Int,account2:Int,money:Long):Boolean{if(!valid(account1)||!valid(account2)||balance[account1-1]<money)return false;balance[account1-1]-=money;balance[account2-1]+=money;return true}fun deposit(account:Int,money:Long):Boolean{if(!valid(account))return false;balance[account-1]+=money;return true}fun withdraw(account:Int,money:Long):Boolean{if(!valid(account)||balance[account-1]<money)return false;balance[account-1]-=money;return true}}
